["{
  "claims": [
    {"id": 1, "text": "Periodic Bloom filter transmission can impose high overhead in communication-constrained distributed systems.", "poster_quote": "Periodic Bloom filter transmission can impose high overhead in communication-constrained distributed systems."},
    {"id": 2, "text": "Lossless compression preserves membership but yields only one size.", "poster_quote": "Lossless compression preserves membership but yields only one size."},
    {"id": 3, "text": "OR folding creates smaller, queryable views with higher FPR while preserving no-false-negative property.", "poster_quote": "OR folding creates smaller, queryable views with higher FPR while preserving no-false-negative property."},
    {"id": 4, "text": "Sender retains canonical filter, constructs FPR-qualified catalog, and selects largest supported view per reporting opportunity.", "poster_quote": "sender retains canonical filter, constructs FPR-qualified catalog, and selects largest supported view per reporting opportunity."},
    {"id": 5, "text": "Goal: improve communication efficiency and receiver freshness under time-varying channels, while preserving no-false-negative property.", "poster_quote": "Goal: improve communication efficiency and receiver freshness under time-varying channels, while preserving no-false-negative property."},
    {"id": 6, "text": "Baselines include complete canonical filter, sparse canonical filter, and four lossless compression methods (gzip, zlib, bzip2, LZMA) at highest compression level.", "poster_quote": "Baselines: complete canonical filter, sparse canonical filter, and four lossless compression methods (gzip, zlib, bzip2, LZMA) at highest compression level."},
    {"id": 7, "text": "Metrics include communication efficiency (successful deliveries per MB of attempted wire bytes), receiver freshness (mean number of intervals since last successful update), and FPR (empirical false positive rate per retained-length ratio).", "poster_quote": "Metrics: (1) Communication efficiency: successful deliveries per MB of attempted wire bytes. (2) Receiver freshness: mean number of intervals since last successful update. (3) FPR: empirical false positive rate per retained-length ratio."},
    {"id": 8, "text": "All strategies use the same channel trace per repetition.", "poster_quote": "All strategies use same channel trace per repetition."},
    {"id": 9, "text": "Datasets used are PhiUSIIL and URL-Phish, with 5,000 malicious URLs inserted and 50,000 benign queries.", "poster_quote": "Datasets: PhiUSIIL and URL-Phish, 5,000 malicious URLs inserted, 50,000 benign queries."},
    {"id": 10, "text": "Sender retains canonical Bloom filter and generates catalog of OR-folded views at various retained-length ratios (e.g., 0.95m, 0.90m, 0.75m).", "poster_quote": "Sender retains canonical Bloom filter and generates catalog of OR-folded views at various retained-length ratios (e.g., 0.95m, 0.90m, 0.75m)."},
    {"id": 11, "text": "Each view is associated with its measured FPR.", "poster_quote": "Each view is associated with its measured FPR."},
    {"id": 12, "text": "At each reporting opportunity, sender selects the largest FPR-qualified view that fits current communication constraints (capacity or loss probability).", "poster_quote": "At each reporting opportunity, sender selects the largest FPR-qualified view that fits current communication constraints (capacity or loss probability)."},
    {"id": 13, "text": "Transmitted update includes view, its length, and timestamp.", "poster_quote": "Transmitted update includes view, its length, and timestamp."},
    {"id": 14, "text": "Receiver installs only newer, fully delivered updates and queries using two-stage coordinate mapping.", "poster_quote": "Receiver installs only newer, fully delivered updates and queries using two-stage coordinate mapping."},
    {"id": 15, "text": "Experiments fix inserted set, canonical length, and hash count to isolate channel effects.", "poster_quote": "Experiments fix inserted set, canonical length, and hash count to isolate channel effects."},
    {"id": 16, "text": "Under Five-State Markov: adaptive folding achieves 191.6 deliveries/MB vs. 66.9 (best compression) and 27.7 (classical filter) — 2.9x and 6.9x improvement.", "poster_quote": "Under Five-State Markov: adaptive folding achieves 191.6 deliveries/MB vs. 66.9 (best compression) and 27.7 (classical filter) — 2.9x and 6.9x improvement."},
    {"id": 17, "text": "Under Gilbert-Elliott: folding (140.5) and best compression (141.8) are comparable, classical filter (119.0) lags.", "poster_quote": "Under Gilbert-Elliott: folding (140.5) and best compression (141.8) are comparable, classical filter (119.0) lags."},
    {"id": 18, "text": "Under Rayleigh: folding (174.9) vs. compression (89.9) and classical (58.2) — 1.9x and 3.0x improvement.", "poster_quote": "Under Rayleigh: folding (174.9) vs. compression (89.9) and classical (58.2) — 1.9x and 3.0x improvement."},
    {"id": 19, "text": "Mean selected FPRs: 4.36% (Five-State), 3.43% (Gilbert-Elliott), 3.34% (Rayleigh), all ≤10% with zero false negatives.", "poster_quote": "Mean selected FPRs: 4.36% (Five-State), 3.43% (Gilbert-Elliott), 3.34% (Rayleigh), all ≤10% with zero false negatives."},
